using System;using System.Linq;using System.Collections.Generic;using BeamScheduleFormatter;
class AdditionalWorksTests {
 static int checks;static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}static void Near(double actual,double expected,string why){Check(Math.Abs(actual-expected)<1e-8,why+": "+actual+" vs "+expected);}static void Reject(Action action,string why){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,why);}
 static void Main(){var cfg=new LengthConfiguration{GradeSmall=40,GradeLarge=60,FySmall=275,FyLarge=420,Input=new LengthInput{Fc=21,Round=25,Simplified=true}};
  var column=MiscStructureTakeoff.Member("Stiffener Column","SC1","Sample",3,150,150,2,40,12,4,12,0,10,"Spacing (mm)",150,50,200,false,0,cfg);Near(column.Concrete,.135,"Column gross concrete");Near(column.Forms,3.6,"Four column sides");Check(column.Steel.Result.Lines.First(l=>l.Part=="Stirrups").TieSetsPerBeam==21,"Tie spacing includes both end stations");Near(column.Steel.Result.Total,column.Steel.Result.Lines.Sum(l=>l.Kg),"Column includes longitudinal/tie kg once");
  var beam=MiscStructureTakeoff.Member("Lintel Beam","LB1","Lintel",2,200,300,1,25,16,2,16,2,10,"Number of ties",10,50,0,true,2,cfg);Near(beam.Concrete,.12,"Beam gross volume");Near(beam.Forms,1.72,"Beam sides, soffit and two formed ends");Check(beam.Steel.Result.Lines.Single(l=>l.Part=="Stirrups").TieSetsPerBeam==10,"Explicit tie count");
  var a=MiscStructureTakeoff.Bars(10,"Number of bars",6);var b=MiscStructureTakeoff.Bars(10,"Spacing (mm)",150);var one=MiscStructureTakeoff.Panel("Countertop","CT1","Top",2,.6,100,1,20,1,a,b,0,0,2,2,true,cfg);var two=MiscStructureTakeoff.Panel("Countertop","CT2","Top",2,.6,100,1,20,2,a,b,0,0,2,2,true,cfg);Near(one.Concrete,.12,"Countertop volume");Near(one.Forms,1.72,"Countertop soffit plus full perimeter edges");Near(two.Steel.Result.Total,2*one.Steel.Result.Total,"Two layers double both rebar directions");Near(two.Concrete,one.Concrete,"Layers do not change concrete");Check(two.Steel.Result.Lines.Count==4,"Two directions per layer");Reject(()=>MiscStructureTakeoff.Bars(10,"Number of bars",3.5),"Fractional bar count rejected");Reject(()=>MiscStructureTakeoff.Member("Lintel Beam","X","Bad",1,100,100,1,40,16,2,16,2,10,"Spacing (mm)",0,50,0,true,0,cfg),"Invalid section/spacing rejected");
  var parapet=MiscStructureTakeoff.Panel("Parapet Wall","P1","Wall",3,1,150,2,25,1,a,b,0,0,2,2,false,cfg);Near(parapet.Concrete,.9,"Parapet volume");Near(parapet.Forms,12.6,"Parapet selected wall faces/ends");
  Near(SiteWorkTakeoff.Area(10,4,2),80,"Clearing/pavement area");Near(SiteWorkTakeoff.Rectangular(10,4,150,2),12,"Pavement excavation/course volume");Near(SiteWorkTakeoff.Stone(10,2,.3,.7,1),10,"Trapezoidal stone masonry");
  foreach(var item in new[]{new{D=150.0,Code="800(3)a1"},new{D=300.0,Code="800(3)a1"},new{D=301.0,Code="800(3)a2"},new{D=500.0,Code="800(3)a2"},new{D=501.0,Code="800(3)a3"},new{D=750.0,Code="800(3)a3"},new{D=751.0,Code="800(3)a4"},new{D=900.0,Code="800(3)a4"},new{D=901.0,Code="800(4)"}})Check(SiteWorkTakeoff.TreeItem(item.D)==item.Code,"Tree diameter boundary "+item.D);Reject(()=>SiteWorkTakeoff.TreeItem(149),"Below-template tree diameter requires review");Check(SiteWorkTakeoff.Grade60Item(new[]{16,25}).Contains("max 25mm"),"All <=25mm use small Grade60 item");Check(SiteWorkTakeoff.Grade60Item(new[]{16,28}).Contains("max 42mm"),"Any >25 routes ALL Grade60 to max42 item");Reject(()=>SiteWorkTakeoff.Grade60Item(new[]{16,50}),"Above42mm does not silently use max42 item");
  var catalogue=BackupPayItemCatalog.Items();Check(BackupMapping.Unit(catalogue.Single(t=>t.Code=="105(1)a").Unit)=="m2","Subgrade catalogue uses prepared area, not volume");var blank=BackupBill.Capture(catalogue,new BackupBillItem[0]);Check(blank.All(item=>!item.ManualQuantity.HasValue&&!item.WorkbookQuantity.HasValue),"Catalogue never imports old quantities or infers LS=1");{var ls=new BackupBillItem{Slot="ls-x",Code="1200(1)",Description="Plumbing Fixtures",Unit="l.s.",WorkbookQuantity=5};Check(ls.ManualDemand()==null,"a quantity already in BACKUP is not taken into the app (23 November 2026)");ls.ManualQuantity=1;Check(ls.ManualDemand()!=null&&ls.ManualDemand().Quantity==1,"a quantity typed in the app is used");}foreach(var code in new[]{"1003(3)","1003(4)","1003(5)","1003(6)","1003(11)a1","1003(14)"})Check(catalogue.Any(c=>c.Code==code),"Requested carpentry item available: "+code);Check(catalogue.Count==266,"All provided BACKUP pay items seeded");Check(catalogue.Count(t=>t.Code=="902(1)a2")==2,"Both Grade60 descriptions share a code");Check(catalogue.Count(t=>t.Code=="1003(3)")==2,"Base and wall cabinets remain separate");Check(catalogue.Single(t=>t.Code=="800(3)a2").Description.Contains("301 - 500"),"Owner-approved tree label correction");
  foreach(string group in new[]{"SlabOnFill","Structural","RoofWaterproof","Footing"}){var rm=BackupPayItemCatalog.Concrete(group,true);var ordinary=BackupPayItemCatalog.Concrete(group,false);Check(rm!=null&&ordinary!=null&&BackupMapping.Identity(rm)!=BackupMapping.Identity(ordinary),"Distinct ready/ordinary target for "+group);int row=rm.Row;string identity=BackupMapping.Identity(rm);rm.Row+=100;Check(identity==BackupMapping.Identity(rm),"Row shifts do not change pay-item identity");rm.Row=row;}
  Check(BackupPayItemCatalog.Concrete("Miscellaneous",false).Row==359,"Misc concrete target differs from wall footing");Check(BackupPayItemCatalog.Concrete("WallFooting",false).Row==369,"Wall footing concrete target");Check(BackupPayItemCatalog.Concrete("Miscellaneous",true)==null,"No invented ready-mix misc target");
  var roof=TimberQuantities.Create("Roof Frame","R1","",2,2,3,1,12,"Pine");var floor=TimberQuantities.Create("Floor Frame","F1","",1,2,3,1,12,"Pine");var purchase=TimberQuantities.Purchase(new[]{roof,floor});Near(roof.Net,2*3*(2/.3048)/12,"Standard board-foot formula");Near(purchase.Values.Sum(),6,"Roof/floor compatible offcuts share one 12ft timber");Near(purchase[roof],4,"Roof share of purchased stock bf");Near(purchase[floor],2,"Floor share of purchased stock bf");Reject(()=>TimberQuantities.Create("Roof Frame","L","",5,2,3,1,12,"Pine"),"No automatic timber splices");
  var steelA=new SteelCutDemand{Member="A",Specification="L50",Length=4,Quantity=1,KgM=3.8};var steelB=new SteelCutDemand{Member="B",Specification="L50",Length=1,Quantity=2,KgM=3.8};var steel=SteelCutPlanner.Allocate(new[]{steelA,steelB});Check(steel.Count==1,"Existing 6m steel allocation unchanged");Near(SteelCutPlanner.PurchaseKg(steel,steelA)+SteelCutPlanner.PurchaseKg(steel,steelB),22.8,"Steel purchase weights unchanged");
  var plan=CommercialBars.Allocate(new[]{one.Steel,two.Steel,column.Steel},cfg,new[]{6.0});double physical=plan.SelectMany(s=>s.Stocks).Distinct().Sum(s=>s.Length*s.Count*EstimatorEngine.UnitMass(s.Diameter));Near(plan.Sum(p=>p.Purchase),physical,"Rebar whole-stock purchase charged once across miscellaneous rows");
  var smallTarget=catalogue.Where(t=>t.Code=="902(1)a2"&&t.Description.Contains("max 25mm")).ToList();Check(RequiredPayRouting.Resolve("902(1)a2","Reinforcing Steel (Deformed), Grade 60, max 42mm dia.","kg",smallTarget)==null,"Large bars cannot fall back to lone max25 target");var baseOnly=catalogue.Where(t=>t.Code=="1003(3)"&&t.Description=="Modular Base Cabinets").ToList();Check(RequiredPayRouting.Resolve("1003(3)","Modular Wall Cabinets","m2",baseOnly)==null,"Wall cabinet cannot fall back to base-only target");foreach(var target in catalogue.Where(t=>t.Code.StartsWith("1003(")))Check(RequiredPayRouting.Resolve(target.Code,target.Description,target.Unit,catalogue)==target,"Carpentry code, full description and unit resolve together");
  Console.WriteLine("PASS: "+checks+" additional-work calculation, pay-item identity, diameter tier and stock-sharing checks");
 }
}
